contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test entry; take depositAmount as parameter and make the function payable
    function run(uint depositAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        // ensure this test contract has enough funds to deposit
        require(address(this).balance >= depositAmount);

        // record contract c balance before any actions
        uint before = address(c).balance;

        // perform a deposit to c to set up state (may be zero)
        c.deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        // try withdrawAll and capture whether it reverted
        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterBalance = address(c).balance;

        // General invariant as a single assert:
        // If withdrawAll reverted then c.balance should equal before + depositAmount (deposit took effect, withdrawal failed).
        // If withdrawAll did not revert then c.balance should be <= before (withdraw transferred funds out, not increasing c's balance).
        assert((reverted && afterBalance == before + depositAmount) || (!reverted && afterBalance <= before));
    }

    receive() external payable {}
}

